const MONEDA=new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN",maximumFractionDigits:0}),COSTO_POR_MINUTO_ADICIONAL=900,COSTO_REVISION_EXTRA=400,REVISIONES_INCLUIDAS=2,selectTipo=document.getElementById("tipo"),rangoDuracion=document.getElementById("duracion"),duracionValor=document.getElementById("duracionValor"),inputRevisiones=document.getElementById("revisiones"),checksExtras=document.querySelectorAll("[data-extra]"),totalEl=document.getElementById("total"),desgloseEl=document.getElementById("desglose");function agregarLinea(e,t){const n=document.createElement("li"),a=document.createElement("span"),c=document.createElement("span");a.textContent=e,c.textContent=MONEDA.format(t),n.appendChild(a),n.appendChild(c),desgloseEl.appendChild(n)}function calcular(){const e=Number(selectTipo.value),t=Number(rangoDuracion.value),n=Math.min(5,Math.max(1,Number(inputRevisiones.value)||1)),a=900*(t-1),c=Math.max(0,n-2),o=400*c;let r=0;checksExtras.forEach(function(e){e.checked&&(r+=Number(e.dataset.extra))});const i=e+a+o+r;duracionValor.textContent=t,totalEl.textContent=MONEDA.format(i)+" MXN",desgloseEl.innerHTML="",agregarLinea("Producción base ("+selectTipo.options[selectTipo.selectedIndex].text+")",e),a>0&&agregarLinea("Minutos adicionales ("+(t-1)+")",a),o>0&&agregarLinea("Revisiones extra ("+c+")",o),r>0&&agregarLinea("Extras seleccionados",r)}selectTipo.addEventListener("change",calcular),rangoDuracion.addEventListener("input",calcular),inputRevisiones.addEventListener("input",calcular),checksExtras.forEach(function(e){e.addEventListener("change",calcular)}),calcular();